module PatientAPI
  module V3
    class ProtocolSerializer
      def initialize(object, scope = nil)
        @object = object
        @scope  = scope
      end

      def as_json(*)
        { id: object.id, title: object.title, startDate: object.started_at&.iso8601 }
      end
    end
  end
end

module Patients
  class Invite
    def self.call(patient:, inviter:, notifier: Notifier.new(patient))
      new(patient:, inviter:, notifier:).call
    end

    def initialize(patient:, inviter:, notifier:)
      @patient = patient
      @inviter = inviter
      @notifier = notifier
    end

    def call
      @notifier.deliver
    end
  end
end

